function currentLang(){return localStorage.getItem("fcLang")||"en"}
function t(key){return (translations[currentLang()]||translations.en)[key]||translations.en[key]||key}
const autoOriginals=new Map();
function restoreAutoText(){autoOriginals.forEach((orig,node)=>{node.nodeValue=orig});}
function translateAutoText(){
  restoreAutoText();
  const lang=currentLang();
  if(lang==='en') return;
  const map=autoTranslations[lang]||{};
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node=>{
    if(!node.parentElement || /^(SCRIPT|STYLE|OPTION)$/i.test(node.parentElement.tagName)) return;
    const original=node.nodeValue;
    const key=original.trim();
    if(map[key]){autoOriginals.set(node,original);node.nodeValue=original.replace(key,map[key]);}
  });
}
function setLanguage(lang){
  if(!translations[lang]) return;
  localStorage.setItem('fcLang',lang); document.documentElement.lang=lang;
  if(lang==='en') restoreAutoText();
  document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));
  document.querySelectorAll('.lang-select').forEach(el=>el.value=lang);
  document.querySelectorAll('[data-i18n-title]').forEach(el=>el.title=t(el.dataset.i18nTitle));
  translateAutoText();
  document.dispatchEvent(new CustomEvent('languageChanged',{detail:lang}));
}
function languageSelector(){return `<select class="lang-select" aria-label="${t('selectLanguage')}" onchange="setLanguage(this.value)">${Object.entries(translations).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select>`}
document.addEventListener('DOMContentLoaded',()=>setLanguage(currentLang()));

